import{_ as a,o as n,c as s,a0 as t}from"./chunks/framework.CNDWyMYS.js";const u=JSON.parse('{"title":"Platform-agnostic external dependencies","description":"","frontmatter":{},"headers":[],"relativePath":"platform_agnostic_external_dependencies.md","filePath":"platform_agnostic_external_dependencies.md"}'),i={name:"platform_agnostic_external_dependencies.md"};function o(l,e,p,c,r,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="platform-agnostic-external-dependencies" tabindex="-1">Platform-agnostic external dependencies <a class="header-anchor" href="#platform-agnostic-external-dependencies" aria-label="Permalink to &quot;Platform-agnostic external dependencies&quot;">​</a></h1><p>Since 0.6, LuaRocks supports specifying files for external dependency search in a platform-agnostic way. When filenames given in the <code>external_dependencies</code> section of a <a href="./rockspec_format.html">rockspec</a> don&#39;t have any dot (&quot;.&quot;) characters, their contents are substituted according to the patterns given in the <code>external_deps_patterns</code> table of the <a href="./config_file_format.html">configuration file</a>.</p><p>These patterns will typically not be used in the configuration file, as LuaRocks provides sensible defaults. The default patterns defined on Unix are:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bin = {&quot;?&quot;}</span></span>
<span class="line"><span>lib = {&quot;lib?.a&quot;, &quot;lib?.so&quot;}</span></span>
<span class="line"><span>include = {&quot;?.h&quot;}</span></span></code></pre></div><p>On Windows the defaults are:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bin = {&quot;?.exe&quot;, &quot;?.bat&quot;}</span></span>
<span class="line"><span>lib = {&quot;?.lib&quot;, &quot;?.dll&quot;}</span></span>
<span class="line"><span>include = {&quot;?.h&quot;}</span></span></code></pre></div><p>For example, a <a href="./rockspec_format.html">rockspec</a> can define an external dependency like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>external_dependencies = {</span></span>
<span class="line"><span>    FOO = {</span></span>
<span class="line"><span>       library = &quot;foo&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span> }</span></span></code></pre></div><p>and this will result in searches for libfoo.a or libfoo.so on Unix systems, and foo.lib or foo.dll on Windows. For entries that have more than one pattern, such as lib, only one entry needs to be satisfied.</p><p>In other words, the value &quot;foo&quot; you see in the external_dependencies.FOO.library entry is the same value you would use when linking the library, for example -lfoo. In addition, once you added FOO in the external_dependencies, this means you can pass entries such as FOO_DIR and FOO_LIBDIR to the <code>luarocks</code> command-line tool, in case you have these libraries in non-standard locations. For example, if the user installed the library in a custom location in their own home directory, it would still be usable, like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks install my_rockspec_using_foo-1.0-1.rockspec FOO_LIBDIR=/home/joeuser/foo/lib</span></span></code></pre></div><p>When performing external dependency checks during installation (as opposed to build) of rocks, static libraries and headers are not searched. The <code>runtime_external_deps_patterns</code> table is used instead.</p><p>Since 3.4.0, the variable DEPS_DIR which doesn&#39;t depend on the name FOO, could also used, like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks install my_rockspec_using_foo-1.0-1.rockspec DEPS_DIR=/home/joeuser/foo/lib</span></span></code></pre></div><h1 id="when-filenames-don-t-match" tabindex="-1">When filenames don&#39;t match <a class="header-anchor" href="#when-filenames-don-t-match" aria-label="Permalink to &quot;When filenames don&#39;t match&quot;">​</a></h1><p>If the pattern system is not enough to hide platform differences, you can always resort to <a href="./platform_overrides.html">per-platform overrides</a>. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>external_dependencies = {</span></span>
<span class="line"><span>   FOO = {</span></span>
<span class="line"><span>      library = &quot;foo&quot;</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>   platforms = {</span></span>
<span class="line"><span>      win32 = {</span></span>
<span class="line"><span>         FOO = {</span></span>
<span class="line"><span>            library = &quot;winfoo32.dll&quot;</span></span>
<span class="line"><span>         }</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h1 id="statically-linked-libraries-and-dependencies" tabindex="-1">Statically linked libraries and dependencies <a class="header-anchor" href="#statically-linked-libraries-and-dependencies" aria-label="Permalink to &quot;Statically linked libraries and dependencies&quot;">​</a></h1><p>If your rock links a library statically, avoid adding a library search in its <a href="./rockspec_format.html">rockspec</a>&#39;s <code>external_dependencies</code> table. Search for a header instead, so that the external dependency search does not fail when users install a binary rock and they don&#39;t have the library installed separately.</p>`,19)])])}const f=a(i,[["render",o]]);export{u as __pageData,f as default};
